import torch

def gen_inputs(ctx, device):
    batch_first = ctx.get("batch_first", False)
    shape = ctx["input__shape"]
    seq = shape[1] if batch_first else shape[0]
    batch = shape[0] if batch_first else shape[1]
    lengths = torch.randint(1, seq + 1, (batch,), dtype=torch.int64, device=device)
    lengths = torch.sort(lengths, descending=True).values
    return {"lengths": lengths}

def run(input, lengths, batch_first):
    return torch._pack_padded_sequence(input, lengths.cpu(), batch_first)
